<?php require 'includes/bootstrap.php';admin_required();$users=$pdo->query('SELECT full_name,email,role,verified_at FROM users ORDER BY id DESC LIMIT 50')->fetchAll();$tx=$pdo->query('SELECT t.*,u.email FROM transactions t JOIN users u ON u.id=t.user_id ORDER BY t.id DESC LIMIT 50')->fetchAll();$pageTitle='Admin';require 'includes/header.php';?><section class="welcome"><div><span class="tag">Restricted access</span><h1>Security administration</h1></div></section><section class="card"><h2>Recent risk decisions</h2><div class="table"><table><tr><th>User</th><th>Amount</th><th>Risk</th><th>Status</th></tr><?php foreach($tx as $t):?><tr><td><?=e($t['email'])?></td><td>GHS <?=number_format((float)$t['amount'],2)?></td><td><?=e($t['risk_level'])?> <?=e((string)$t['risk_score'])?></td><td><?=e($t['status'])?></td></tr><?php endforeach?></table></div></section><section class="card"><h2>Users</h2><div class="table"><table><tr><th>Name</th><th>Email</th><th>Role</th><th>Verified</th></tr><?php foreach($users as $x):?><tr><td><?=e($x['full_name'])?></td><td><?=e($x['email'])?></td><td><?=e($x['role'])?></td><td><?=$x['verified_at']?'Yes':'No'?></td></tr><?php endforeach?></table></div></section><?php require 'includes/footer.php';?>
